CREATE OR REPLACE VIEW vessel_traffic.domain_events AS
SELECT id,
       aggregate_type,
       aggregate_id,
       event_type,
       payload,
       occurred_at,
       processed_at,
       retry_count,
       last_retry_at,
       NULL::UUID AS actor_id,
       NULL::TEXT AS actor_name,
       created_at
FROM vessel_traffic.outbox
;

